def apply_edit(session, request):
    session.history.append(request)
    if session.turns_since_anchor >= session.reanchor_every:
        merged = "; then ".join(session.history)      # one compound instruction
        session.latest = editor(session.original, merged)
        session.turns_since_anchor = 0
    else:
        session.latest = editor(session.latest, request)  # cheap turn, drifts a little
        session.turns_since_anchor += 1
    return session.latest
